/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { MatSnackBar } from '@angular/material/snack-bar';
import { TranslocoService } from '@jsverse/transloco';
import { of } from 'rxjs';
import { NotifyService } from './notify.service';

describe('NotifyService', () => {
  let snackBar: jasmine.SpyObj<MatSnackBar>;
  let service: NotifyService;

  beforeEach(() => {
    snackBar = jasmine.createSpyObj<MatSnackBar>('MatSnackBar', ['open']);
    const transloco = {
      selectTranslate: (key: string, params?: any) => of(params ? `${key}:${JSON.stringify(params)}` : `t(${key})`),
    };
    TestBed.configureTestingModule({
      providers: [
        { provide: MatSnackBar, useValue: snackBar },
        { provide: TranslocoService, useValue: transloco },
      ],
    });
    service = TestBed.inject(NotifyService);
  });

  it('shows a translated success message with the default close action', () => {
    service.success('a.saved');

    expect(snackBar.open).toHaveBeenCalledWith('t(a.saved)', 't(common.notify.close)', {
      duration: 3000,
      panelClass: 'notify-success',
    });
  });

  it('passes params and a custom action', () => {
    service.info('a.info', { n: 2 }, 'a.undo');

    expect(snackBar.open).toHaveBeenCalledWith('a.info:{"n":2}', 't(a.undo)', {
      duration: 5000,
      panelClass: 'notify-info',
    });
  });

  it('keeps errors visible longer', () => {
    service.error('a.failed');

    expect(snackBar.open.calls.mostRecent().args[2]).toEqual({ duration: 8000, panelClass: 'notify-error' });
  });
});
